<?php require_once __DIR__.'/../includes/functions.php';$u=require_login();$id=(int)($_GET['id']??0);$q=db()->prepare('SELECT g.*,s.name subject FROM study_groups g LEFT JOIN subjects s ON s.id=g.subject_id WHERE g.id=? AND g.status=\'active\'');$q->execute([$id]);$g=$q->fetch();if(!$g){http_response_code(404);exit('Group not found');}$m=db()->prepare('SELECT u.name,p.course,m.role,u.id FROM group_members m JOIN users u ON u.id=m.user_id JOIN student_profiles p ON p.user_id=u.id WHERE m.group_id=? ORDER BY m.role DESC,u.name');$m->execute([$id]);page_start('Study group'); ?><div class="row g-4"><div class="col-lg-8"><div class="card"><div class="card-body p-4"><span class="tag"><?= e($g['level']) ?></span><span class="tag"><?= e($g['study_mode']) ?></span><h2 class="mt-3"><?= e($g['name']) ?></h2><p class="text-secondary"><?= nl2br(e($g['description'])) ?></p><div><strong>Subject:</strong> <?= e($g['subject']?:'Open topic') ?></div><div class="mt-4"><h3 class="h5">Members</h3><?php foreach($m as $x): ?><div class="d-flex gap-2 align-items-center border-top py-2"><div class="avatar avatar-sm"><?= e(mb_substr($x['name'],0,1)) ?></div><a href="profile.php?id=<?= $x['id'] ?>"><?= e($x['name']) ?></a><span class="text-secondary small"><?= e($x['course']) ?></span><span class="tag ms-auto"><?= e($x['role']) ?></span></div><?php endforeach ?></div><a class="btn btn-outline-primary mt-3" href="groups.php">Back to groups</a></div></div></div><div class="col-lg-4"><div class="card"><div class="card-body"><h3 class="h6">Group sessions</h3><?php $ss=db()->prepare("SELECT * FROM study_sessions WHERE group_id=? AND status='scheduled' AND session_date>=CURDATE() ORDER BY session_date");$ss->execute([$id]);foreach($ss as $s): ?><div class="border-top py-2"><strong><?= e($s['title']) ?></strong><div class="small text-secondary"><?= e($s['session_date']) ?> · <?= e(substr($s['start_time'],0,5)) ?></div></div><?php endforeach ?><a class="btn btn-sm btn-primary mt-3" href="sessions.php?group=<?= $id ?>">Schedule group session</a></div></div></div></div><?php page_end(); ?>
